    float c00 = 0.0f;
    float c01 = 0.0f;
    float c10 = 0.0f;
    float c11 = 0.0f;

    // Loop over tiles
    for (int t = 0; t < N; t += BLOCK_SIZE) {
        // Load tile from A into shared memory (coalesced access)
        if (row < N && (t + tx) < N) {
            As[ty][tx] = A[row * N + t + tx];
            As[ty+1][tx] = A[(row+1) * N + t + tx];
        } else {
            As[ty][tx] = 0.0f;
            As[ty+1][tx] = 0.0f;
        }

        // Load tile from B into shared memory (coalesced access)
        if (col < N && (t + ty) < N) {
